;padding:10px 18px;color:#4169d8;cursor:pointer}.catalog-search-status{font-size:12px;color:#74869f;margin:0 0 20px}.catalog-page :is(a,button,input):focus-visible,.catalog-scroll:focus-visible{outline:2px solid #7298de;outline-offset:3px}
@media(max-width:1100px){.catalog-cards{grid-template-columns:repeat(2,minmax(0,1fr))}.catalog-search{width:240px}}
@media(max-width:760px){.catalog-head{padding:20px 18px 0}.catalog-intro{gap:16px;align-items:stretch;flex-direction:column}.catalog-identity img{width:44px;height:44px}.catalog-identity h1{font-size:24px}.catalog-identity p{font-size:12px}.catalog-search{width:100%}.catalog-search label{display:none}.catalog-nav{padding:14px 0 17px;gap:8px}.catalog-nav>span{display:none}.catalog-nav button{padding:8px 10px}.catalog-scroll{padding:22px 18px 40px}.catalog-card{padding:17px 15px;min-height:152px;gap:10px}.catalog-group-heading p{font-size:11px}}
@media(max-width:520px){.catalog-cards{grid-template-columns:minmax(0,1fr)}.catalog-card{min-height:130px}.catalog-group{margin-bottom:28px}.catalog-identity{gap:12px}.catalog-identity .eyebrow{font-size:9px}.catalog-card h3{font-size:15px}.catalog-tool-icon{width:35px;height:35px}}
@media(prefers-reduced-motion:reduce){.catalog-card{transition:none}.catalog-card:hover{transform:none}}
</style>
<style scoped>
.catalog-group:last-child{min-height:calc(100% + 2px)}
</style>
